for(const category of INSPIRATION_CATEGORIES){
 const details=ROOM_CATEGORY_DETAILS[category.slug];
 if(!details)continue;
 Object.assign(category,details);
 category.gallery=details.photos.map(([photo,alt])=>({src:inspirationImage(photo,1200),alt}));
 category.heroImage=category.gallery[0].src;
 category.heroAlt=category.gallery[0].alt;
 category.seoTitle=`${category.name} Design Ideas | Tarangan Associates`;
 category.metaDescription=category.description;
}
INSPIRATION_CATEGORIES.push({
 slug:"home-office",route:"#/inspiration/home-office",order:INSPIRATION_CATEGORIES.length+1,
 ...ROOM_CATEGORY_DETAILS["home-office"],
 gallery:ROOM_CATEGORY_DETAILS["home-office"].photos.map(([photo,alt])=>({src:inspirationImage(photo,1200),alt})),
 heroImage:inspirationImage(ROOM_CATEGORY_DETAILS["home-office"].photos[0][0]),
 heroAlt:ROOM_CATEGORY_DETAILS["home-office"].photos[0][1],
 seoTitle:"Home Office Ideas | Tarangan Associates",
 metaDescription:ROOM_CATEGORY_DETAILS["home-office"].description
});
function renderInspirationCards(categories,mode="home"){
 return categories.map(category=>`<article class="inspiration-card ${mode==="home"?`inspiration-card--${category.slug}`:""}"><a class="inspiration-card-link" href="${category.route}" aria-label="Explore ${category.name} design inspiration"><img src="${category.gallery[0].src.replace("w=1200","w=900")}" alt="${category.gallery[0].alt}" loading="lazy" decoding="async" width="900" height="650"><span class="inspiration-card-caption"><span class="inspiration-card-kicker">DESIGN INSPIRATION</span><span class="inspiration-card-title">${category.name}</span><span class="inspiration-card-arrow" aria-hidden="true">↗</span></span></a><p class="inspiration-card-description">${category.description}</p></article>`).join("");
}
function renderInspirationOverview(){
 return `<section class="section inspiration-overview"><div class="container"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#/home">Home</a><span aria-hidden="true"> / </span><span>Inspiration</span></nav><div class="section-heading"><div><p class="eyebrow">Explore your inspiration</p><h1>Interior Design Inspiration</h1></div><p>Thoughtful ideas for the rooms and details that make a home your own.</p></div><div class="inspiration-grid inspiration-grid--overview">${renderInspirationCards(INSPIRATION_CATEGORIES,"overview")}</div><p class="inspiration-note">Images are illustrative design inspiration and are not represented as completed Tarangan Associates projects.</p></div></section><section class="cta-band"><div class="container cta-inner"><div><p class="eyebrow">A considered next step</p><h2>Planning a Similar Space?</h2><p>Tell us about your home and the ideas you would like to explore.</p></div><a class="btn" href="#/contact">Book a Consultation</a></div></section>`;
}
function renderInspirationCategory(category){
 const related=category.related.map(slug=>INSPIRATION_CATEGORIES.find(item=>item.slug===slug)).filter(Boolean);
 const content=category.sections.map((section,index)=>`<section><h2>${escapeProjectHtml(section.title)}</h2>${section.paragraphs.slice(0,index===0?2:1).map(paragraph=>`<p>${escapeProjectHtml(paragraph)}</p>`).join("")}</section>`).join("");
 const gallery=category.gallery.map((image,index)=>`<figure><button class="inspiration-gallery-button" type="button" data-gallery-image="${escapeProjectHtml(image.src)}" data-gallery-alt="${escapeProjectHtml(image.alt)}" aria-label="View larger image ${index+1}: ${escapeProjectHtml(image.alt)}"><img src="${escapeProjectHtml(image.src)}" alt="${escapeProjectHtml(image.alt)}" loading="${index<2?"eager":"lazy"}" decoding="async" width="900" height="650"></button><figcaption>${escapeProjectHtml(image.alt)}</figcaption></figure>`).join("");
 return `<section class="inspiration-category"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#/home">Home</a><span aria-hidden="true"> / </span><a href="#/inspiration">Inspiration</a><span aria-hidden="true"> / </span><span>${escapeProjectHtml(category.name)}</span></nav><header class="inspiration-intro container"><p class="eyebrow">${escapeProjectHtml(category.name)} INTERIOR DESIGN</p><h1>${escapeProjectHtml(category.title)}</h1><p>${escapeProjectHtml(category.intro)}</p></header><section class="section inspiration-detail"><div class="container"><div class="inspiration-gallery" aria-label="${escapeProjectHtml(category.name)} image gallery">${gallery}</div><p class="inspiration-note">These Unsplash images are illustrative design references, not verified Tarangan Associates project photography.</p><article class="inspiration-content">${content}</article><section class="inspiration-consultation"><div><p class="eyebrow">A considered next step</p><h2>Planning your ${escapeProjectHtml(category.name.toLowerCase())}?</h2><p>Share your priorities and room details with Tarangan Associates to discuss a design direction tailored to your home.</p></div><a class="btn" href="#/contact">Discuss your ${escapeProjectHtml(category.name.toLowerCase())} project</a></section><div class="related-inspirations"><div class="section-heading"><div><p class="eyebrow">Continue exploring</p><h2>Related Pages</h2></div><a class="text-link" href="#/inspiration">View all inspirations →</a></div><div class="inspiration-grid inspiration-grid--related">${renderInspirationCards(related,"related")}</div></div></div></section><section class="inspiration-return container"><a class="text-link" href="#/inspiration">← All inspirations</a><a class="text-link" href="#/home">Return to home →</a></section></section>`;
}
function renderInspirationNotFound(){
 return `<section class="section"><div class="container legal-copy"><p class="eyebrow">Inspiration</p><h1>That inspiration page could not be found.</h1><p>Browse all room and interior ideas or return to the homepage.</p><p><a class="btn" href="#/inspiration">View All Inspirations</a> <a class="text-link" href="#/home">Home</a></p></div></section>`;
}
