const UPCOMING_PROJECTS = [];
function escapeProjectHtml(value){return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function publishedUpcomingProjects(){return UPCOMING_PROJECTS.filter(project=>project.is_published)}
function renderUpcomingProjectCard(project){
 const href=`#/upcoming-projects/${encodeURIComponent(project.id)}`;
 return `<article class="upcoming-project-card"><a class="upcoming-project-card-link" href="${href}"><div class="upcoming-project-image"><img src="${escapeProjectHtml(project.image_url)}" alt="${escapeProjectHtml(project.title)}" loading="lazy" decoding="async"><span class="upcoming-project-status">${escapeProjectHtml(project.status)}</span></div><div class="upcoming-project-copy"><p class="upcoming-project-category">${escapeProjectHtml(project.category)}</p><h3>${escapeProjectHtml(project.title)}</h3><p class="upcoming-project-location">${escapeProjectHtml(project.location)}</p><p class="upcoming-project-description">${escapeProjectHtml(project.description)}</p><span class="upcoming-project-more">Explore project <span aria-hidden="true">→</span></span></div></a></article>`
}
function renderUpcomingProjectListing(){
 const projects=publishedUpcomingProjects();
 return `<section class="section upcoming-projects-listing"><div class="container"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#/home">Home</a><span aria-hidden="true"> / </span><span>Upcoming Projects</span></nav><div class="section-heading upcoming-projects-heading"><div><p class="eyebrow">A look ahead</p><h1>Upcoming Projects</h1><p>A glimpse into the spaces we're bringing to life.</p></div></div><div class="upcoming-project-grid">${projects.map(renderUpcomingProjectCard).join("")}</div>${projects.length?"":'<p class="upcoming-project-note">No published projects are available right now.</p>'}</div></section><section class="upcoming-project-return container"><a class="text-link" href="#/home">← Return to Home</a></section>`
}
function renderUpcomingProjectsHomeSection(){
 const projects=publishedUpcomingProjects();
 return `<section class="section upcoming-projects-home"><div class="container"><div class="section-heading upcoming-projects-heading"><div><p class="eyebrow">A look ahead</p><a class="upcoming-projects-title-link" href="#/upcoming-projects"><h2>Upcoming Projects</h2></a><p>A glimpse into the spaces we're bringing to life.</p></div><a class="text-link" href="#/upcoming-projects">View All Projects →</a></div><div class="upcoming-project-grid">${projects.map(renderUpcomingProjectCard).join("")}</div>${projects.length?"":'<p class="upcoming-project-note">No published projects are available right now.</p>'}</div></section>`
}
