function markLeadFieldRequired(form,name){
 const field=form.elements.namedItem(name);
 if(!field)return;
 field.required=true;
 const label=field.closest("label")||form.querySelector(`label[for="${field.id}"]`);
 if(!label)return;
 const optional=label.querySelector(".optional-label");
 if(optional){
  optional.classList.remove("optional-label");
  optional.textContent="*";
  optional.setAttribute("aria-hidden","true");
  return;
 }
 const optionalText=[...label.childNodes].find(node=>node.nodeType===Node.TEXT_NODE&&/\(optional\)/i.test(node.textContent));
 if(optionalText)optionalText.textContent=optionalText.textContent.replace(/\s*\(optional\)/i," ");
 if(!label.querySelector("[data-required-indicator]")){
  const indicator=document.createElement("span");
  indicator.dataset.requiredIndicator="true";
  indicator.textContent="*";
  indicator.setAttribute("aria-hidden","true");
  label.append(" ",indicator);
 }
}
