function calculatorRouteFromTarget(target){
 const explicit=target.dataset.calculatorOpen;
 if(explicit&&calculatorRoutes.has(explicit))return explicit;
 const href=target.getAttribute("href")||"";
 const match=href.match(/(?:^|[#/])(interior-cost-estimator|kitchen-cost-estimator|wardrobe-cost-estimator)(?:\.html)?(?:[?#]|$)/i);
 return match?match[1].toLowerCase():"";
}
function releaseCalculatorGate(){
 const calculator=main.querySelector("[data-calculator]");
 calculator?.closest(".section")?.removeAttribute("hidden");
 main.querySelector("[data-calculator-gate]")?.remove();
}
function requireCalculatorLead(page){
 const calculator=main.querySelector("[data-calculator]");
 if(!calculator||calculatorAccessGranted)return;
 const section=calculator.closest(".section");
 if(!section)return;
 section.hidden=true;
 if(!main.querySelector("[data-calculator-gate]")){
  const gate=document.createElement("div");
  gate.className="calculator-gate";
  gate.dataset.calculatorGate="";
  gate.innerHTML='<p class="eyebrow">A considered estimate</p><h2>Start with your project details</h2><p>Submit a short enquiry before opening this planning calculator.</p><button class="btn" type="button" data-open-calculator-gate>Get Your Project Estimate</button>';
  section.before(gate);
 }
 pendingCalculatorRoute=page;
 openConsultation(null,"calculator");
}
document.addEventListener("click",event=>{
 const control=event.target.closest("a[href],button[data-calculator-open],button[data-open-calculator-gate]");
 if(!control)return;
 if(control.matches("[data-open-calculator-gate]")){
  event.preventDefault();
  openConsultation(control,"calculator");
  return;
 }
 const calculatorRoute=calculatorRouteFromTarget(control);
 if(calculatorRoute&&!calculatorAccessGranted){
  event.preventDefault();
  pendingCalculatorRoute=calculatorRoute;
  openConsultation(control,"calculator");
  return;
 }
 const callLink=control.matches('a[href^="tel:"]');
 const consultationLink=/book\s+(?:a|your)\s+consultation/i.test(control.textContent)||control.classList.contains("consult-btn");
 if(!callLink&&!consultationLink)return;
 if(callLink&&!control.closest("[data-consultation-trigger]")&&!consultationLink)return;
 event.preventDefault();
 openConsultation(control,"call");
 if(projectTypeField instanceof HTMLSelectElement&&control.dataset.consultationService)projectTypeField.value=control.dataset.consultationService;
});
function observeConsultationSection(page){
 consultationObserver?.disconnect();consultationObserver=null;
 if(page!=="home")return;
 const thirdSection=main.querySelectorAll(":scope > section")[2];
 if(!thirdSection)return;
 thirdSection.dataset.consultationTrigger="";
 if(consultationAutoShown||!("IntersectionObserver" in window))return;
 consultationObserver=new IntersectionObserver(entries=>{
  if(entries.some(entry=>entry.isIntersecting)){
   consultationObserver.disconnect();
   consultationObserver=null;
   thirdSection.setAttribute("tabindex","-1");
   openConsultation(thirdSection,"call",true);
  }
 },{threshold:0.12});
 consultationObserver.observe(thirdSection);
}
