function initReviewCarousel(){
 clearInterval(reviewCarouselTimer);
 reviewCarouselTimer=null;
 if(reviewCarouselMotionQuery&&reviewCarouselMotionHandler){
  reviewCarouselMotionQuery.removeEventListener?.("change",reviewCarouselMotionHandler);
  reviewCarouselMotionQuery=null;
  reviewCarouselMotionHandler=null;
 }
 const grid=document.querySelector(".testimonial-grid");
 if(!grid)return;
 const cards=[...grid.querySelectorAll(":scope > .testimonial")];
 if(!cards.length)return;
 const wrapper=document.createElement("div");
 wrapper.className="review-carousel";
 grid.before(wrapper);
 wrapper.append(grid);
 grid.classList.add("review-carousel-track");
 const controls=document.createElement("div");
 controls.className="review-carousel-controls";
 controls.setAttribute("aria-label","Review navigation");
 const previous=document.createElement("button");
 previous.className="review-carousel-arrow";
 previous.type="button";
 previous.setAttribute("aria-label","Previous review");
 previous.textContent="←";
 const dots=document.createElement("div");
 dots.className="review-carousel-dots";
 dots.setAttribute("role","group");
 dots.setAttribute("aria-label","Choose a review");
 const next=document.createElement("button");
 next.className="review-carousel-arrow";
 next.type="button";
 next.setAttribute("aria-label","Next review");
 next.textContent="→";
 controls.append(previous,dots,next);
 wrapper.append(controls);
 const more=document.createElement("a");
 more.className="review-carousel-more";
 more.href="https://www.google.com/maps/place/Tarangan+Associates+Bhandara/@21.1640414,79.6389001,16z/data=!4m12!1m2!2m1!1sTarangan+Associates!3m8!1s0x3a2b39bf8c00694f:0x83a4cf52fad8039c!8m2!3d21.1640414!4d79.6484273!9m1!1b1!15sChNUYXJhbmdhbiBBc3NvY2lhdGVzWhUiE3RhcmFuZ2FuIGFzc29jaWF0ZXOSARFpbnRlcmlvcl9kZXNpZ25lcuABAA!16s%2Fg%2F11nyf7xhs7?entry=ttu&g_ep=EgoyMDI2MTAxMy4wIKXMDSoASAFQAw%3D%3D";
 more.target="_blank";
 more.rel="noopener noreferrer";
 more.textContent="View More Reviews on Google ↗";
 wrapper.append(more);
 let activeIndex=0;
 const reducedMotion=window.matchMedia("(prefers-reduced-motion: reduce)");
 function showReview(index){
  activeIndex=(index+cards.length)%cards.length;
  cards.forEach((card,i)=>{
   const active=i===activeIndex;
   card.classList.toggle("is-active",active);
   card.setAttribute("aria-hidden",String(!active));
   card.inert=!active;
  });
  dots.querySelectorAll("button").forEach((dot,i)=>{
   dot.setAttribute("aria-current",String(i===activeIndex));
   dot.setAttribute("aria-label",`Show review ${i+1} of ${cards.length}${i===activeIndex?" (current)":""}`);
  });
 }
 cards.forEach((card,i)=>{
  const dot=document.createElement("button");
  dot.className="review-carousel-dot";
  dot.type="button";
  dot.setAttribute("aria-current","false");
  dot.setAttribute("aria-label",`Show review ${i+1} of ${cards.length}`);
  dot.addEventListener("click",()=>{showReview(i);startAutoRotation()});
  dots.append(dot);
 });
 showReview(0);
 previous.addEventListener("click",()=>{showReview(activeIndex-1);startAutoRotation()});
 next.addEventListener("click",()=>{showReview(activeIndex+1);startAutoRotation()});
 function startAutoRotation(){
  clearInterval(reviewCarouselTimer);
  reviewCarouselTimer=null;
  if(!reducedMotion.matches&&wrapper.isConnected&&!wrapper.matches(":hover")&&!wrapper.contains(document.activeElement)&&touchStartX===null){
   reviewCarouselTimer=window.setInterval(()=>showReview(activeIndex+1),1500);
  }
 }
 function pauseAutoRotation(){
  clearInterval(reviewCarouselTimer);
  reviewCarouselTimer=null;
 }
 wrapper.addEventListener("mouseenter",pauseAutoRotation);
 wrapper.addEventListener("mouseleave",startAutoRotation);
 wrapper.addEventListener("focusin",pauseAutoRotation);
 wrapper.addEventListener("focusout",event=>{
  if(!wrapper.contains(event.relatedTarget))startAutoRotation();
 });
 let touchStartX=null;
 wrapper.addEventListener("touchstart",event=>{
  touchStartX=event.changedTouches[0]?.clientX??null;
  pauseAutoRotation();
 },{passive:true});
 wrapper.addEventListener("touchend",event=>{
  const touchEndX=event.changedTouches[0]?.clientX;
  if(touchStartX!==null&&touchEndX!==undefined){
   const distance=touchEndX-touchStartX;
   if(Math.abs(distance)>40)showReview(activeIndex+(distance<0?1:-1));
  }
  touchStartX=null;
  startAutoRotation();
 },{passive:true});
 reviewCarouselMotionQuery=reducedMotion;
 reviewCarouselMotionHandler=()=>reducedMotion.matches?pauseAutoRotation():startAutoRotation();
 reducedMotion.addEventListener?.("change",reviewCarouselMotionHandler);
 startAutoRotation();
}
