 $$('[data-filter-group]').forEach(g=>{const cards=$$('[data-filter]',g),buttons=$$('[data-filter-value]',g);buttons.forEach(b=>b.onclick=()=>{buttons.forEach(x=>x.classList.toggle('active',x===b));let n=0;cards.forEach(c=>{const show=b.dataset.filterValue==='all'||(c.dataset.filter||"").split(' ').includes(b.dataset.filterValue);c.hidden=!show;if(show)n++});const empty=$('.empty-state',g);if(empty)empty.hidden=n>0})});
 const calc=$('[data-calculator]');if(calc){const type=calc.dataset.calculator,money=n=>'₹'+Math.round(n).toLocaleString('en-IN');const update=()=>{const area=+$('#area',calc)?.value||900,finish=$('#finish',calc)?.value||'premium',mult={essential:1450,premium:2050,luxury:2850}[finish]||2050;let low=area*mult*.82,high=area*mult*1.18;if($('#kitchen',calc)?.checked){low+=100000;high+=260000}if($('#wardrobes',calc)?.checked){low+=80000;high+=220000}if($('#renovation',calc)?.checked){low+=60000;high+=180000}if(type==="home"){const output=calc.closest(".calc-layout");const lowOutput=$('.estimate-low',output),highOutput=$('.estimate-high',output);if(lowOutput)lowOutput.textContent=money(low);if(highOutput)highOutput.textContent=money(high)}};$$('input,select',calc).forEach(x=>x.addEventListener('input',update));update()}
