let publicSupabaseClientPromise;
function getPublicSupabaseClient(){
 if(!publicSupabaseClientPromise){
  publicSupabaseClientPromise=(async()=>{
   if(!window.TARANGAN_SUPABASE_CONFIG){
    await new Promise((resolve,reject)=>{
     const script=document.createElement("script");
     script.src="supabase-config.js";
     script.onload=resolve;
     script.onerror=()=>reject(new Error("Supabase configuration file failed to load."));
     document.head.append(script);
    });
   }
   const config=window.TARANGAN_SUPABASE_CONFIG;
   if(!config?.url||!config?.anonKey)return null;
   if(!window.supabase?.createClient){
    await new Promise((resolve,reject)=>{
     const script=document.createElement("script");
     script.src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2";
     script.onload=resolve;
     script.onerror=()=>reject(new Error("Supabase client CDN failed to load."));
     document.head.append(script);
    });
   }
   return window.supabase.createClient(config.url,config.anonKey);
  })();
 }
 return publicSupabaseClientPromise;
}
function setEnquiryStatus(form,message,isError,whatsappUrl=""){
 const status=form.querySelector(".form-status");
 if(!status)return;
 status.replaceChildren();
 status.textContent=message;
 status.hidden=false;
 status.style.display="block";
 status.classList.toggle("is-error",isError);
 if(whatsappUrl&&!isError){
  const link=document.createElement("a");
  link.href=whatsappUrl;
  link.target="_blank";
  link.rel="noopener noreferrer";
  link.textContent="Open WhatsApp enquiry ↗";
  status.append(document.createTextNode(" "),link);
 }
}
async function insertPublicLead(enquiry){
 const requiredFields={
  client_name:"your full name",
  email:"your email address",
  phone:"your phone number",
  location:"your project location",
  project_type:"your project type",
  work_scope:"your project scope",
  start_timeline:"your expected start timeline",
  lead_status:"an initial lead status"
 };
 const missing=Object.entries(requiredFields)
  .filter(([column])=>!String(enquiry[column]??"").trim())
  .map(([,label])=>label);
 if(missing.length)throw new Error(`Please provide ${missing.join(", ")} before submitting.`);
 const client=await getPublicSupabaseClient();
 if(!client)throw new Error("Supabase is not configured. Your enquiry has not been saved.");
 const {error}=await client.from("leads").insert(enquiry);
 if(error){
  const failure=new Error(error.message||"The enquiry could not be saved.");
  failure.code=error.code;
  failure.details=error.details;
  failure.hint=error.hint;
  throw failure;
 }
}
function leadFormValue(formData,...names){
 for(const name of names){
  const value=String(formData.get(name)||"").trim();
  if(value)return value;
 }
 return "";
}
function buildPublicLead(formData){
 const projectType=leadFormValue(formData,"project_type","property_type");
 const workScope=[
  leadFormValue(formData,"property_type")&&`Property type: ${leadFormValue(formData,"property_type")}`,
  leadFormValue(formData,"property_size")&&`Property size: ${leadFormValue(formData,"property_size")}`
 ].filter(Boolean).join("\n")||projectType;
 const details=leadFormValue(formData,"details","additional_requirements","description");
 const budget=leadFormValue(formData,"budget","budget_range");
 return {
  client_name:leadFormValue(formData,"client_name","full_name"),
  email:leadFormValue(formData,"email"),
  phone:leadFormValue(formData,"phone","phone_number"),
  location:leadFormValue(formData,"location","city"),
  project_type:projectType,
  work_scope:workScope,
  start_timeline:leadFormValue(formData,"start_timeline","start_date"),
  lead_status:"New",
  ...(budget?{budget}:{}),
  ...(details?{details}:{})
 };
}
async function submitLeadCapture(event){
 event.preventDefault();
 const form=event.currentTarget;
 if(form!==leadCaptureForm)throw new Error("The consultation form could not be identified. Please reload and try again.");
 if(form.dataset.submitting==="true"||form.dataset.submitted==="true")return;
 if(!form.reportValidity())return;
 const submitButton=form.querySelector('[type="submit"]');
 const formData=new FormData(form);
 if(!formData.get("consent")){
  setEnquiryStatus(form,"Please agree to the privacy notice before submitting.",true);
  return;
 }
 const enquiry=buildPublicLead(formData);
 form.dataset.submitting="true";
 submitButton.disabled=true;
 submitButton.textContent="Submitting…";
 leadCaptureStatus.hidden=true;
 leadCaptureStatus.textContent="";
 leadCaptureStatus.classList.remove("is-error");
 try{
  await insertPublicLead(enquiry);
  form.reset();
  form.dataset.submitted="true";
  leadCaptureFields.hidden=true;
  leadCaptureSuccess.textContent=LEAD_SUCCESS_MESSAGE;
  leadCaptureSuccess.hidden=false;
  if(captureMode==="call"){
   leadCaptureCall.hidden=false;
  }else{
   calculatorAccessGranted=true;
   leadCaptureContinue.hidden=false;
   leadCaptureContinue.focus();
   const target=pendingCalculatorRoute;
   pendingCalculatorRoute="";
   if(target&&routeKey()!==target){
    location.hash=`#/${target}`;
   }else{
    releaseCalculatorGate();
   }
  }
 }catch(error){
   console.error("[Lead submission] Consultation enquiry insert failed.",{
    message:error.message||"Unknown Supabase error",
    code:error.code||null,
    details:error.details||null,
    hint:error.hint||null
   });
  setEnquiryStatus(form,`Your enquiry was not saved. ${error.message} Please try again.`,true);
 }finally{
  form.dataset.submitting="false";
  submitButton.disabled=form.dataset.submitted==="true";
  if(form.dataset.submitted==="true"){
   submitButton.textContent="Submitted";
  }else{
   submitButton.textContent=captureMode==="calculator"?"Submit details and continue":"Submit enquiry";
  }
 }
}
async function submitEnquiry(form){
 const submitButton=form.querySelector('[type="submit"]');
 if(form.dataset.submitting==="true"||form.dataset.submitted==="true")return;
 if(!form.reportValidity())return;
 const formData=new FormData(form);
 if(!formData.get("consent")){
  setEnquiryStatus(form,"Please agree to the privacy notice before submitting.",true);
  return;
 }
 const enquiry=buildPublicLead(formData);
 const submittedValues=Object.fromEntries([...formData.entries()]
  .filter(([name,value])=>name!=="consent"&&String(value).trim())
  .map(([name,value])=>[name,String(value).trim()]));
 const labels={full_name:"Name",phone_number:"Phone",email:"Email",city:"City",property_type:"Property type",project_type:"Project type",property_size:"Property size",budget_range:"Budget",start_date:"Preferred start",description:"Project details"};
 const message=["Hello Tarangan Associates, I would like to enquire about a project.",...Object.entries(submittedValues).map(([name,value])=>`${labels[name]||name}: ${value}`)].join("\n");
 const whatsappUrl=`https://wa.me/919860773107?text=${encodeURIComponent(message)}`;
 const originalButtonLabel=submitButton?.textContent||"Prepare WhatsApp Enquiry ↗";
 form.dataset.submitting="true";
 if(submitButton){submitButton.disabled=true;submitButton.textContent="Submitting…"}
 try{
  await insertPublicLead(enquiry);
  form.reset();
  form.dataset.submitted="true";
  setEnquiryStatus(form,LEAD_SUCCESS_MESSAGE,false,whatsappUrl);
 }catch(error){
  console.error("[Lead submission] Website enquiry insert failed.",{
   message:error.message||"Unknown Supabase error",
   code:error.code||null,
   details:error.details||null,
   hint:error.hint||null
  });
  setEnquiryStatus(form,`Your enquiry was not saved: ${error.message}. Please try again.`,true);
 }finally{
  form.dataset.submitting="false";
  if(submitButton){
   submitButton.disabled=form.dataset.submitted==="true";
   submitButton.textContent=form.dataset.submitted==="true"?"Enquiry submitted":originalButtonLabel;
  }
 }
}
